import{NextResponse}from'next/server';import{createClient}from'@/lib/supabase/server';import{createAdminClient}from'@/lib/supabase/admin';import{fetchRazorpayPayment}from'@/lib/payments/razorpay-api';import{verifyRazorpayPaymentSignature}from'@/lib/payments/razorpay';import{isAllowedOrigin,jsonSecurityHeaders}from'@/lib/security';import{readBoundedText}from'@/lib/security/request';
export async function POST(request:Request){if(!isAllowedOrigin(request))return new NextResponse(null,{status:403,headers:jsonSecurityHeaders()});try{const s=await createClient(),{data:{user}}=await s.auth.getUser();if(!user)return NextResponse.json({error:'Authentication required'},{status:401,headers:jsonSecurityHeaders()});const body=JSON.parse(await readBoundedText(request)),orderId=String(body?.razorpay_order_id||''),paymentId=String(body?.razorpay_payment_id||''),signature=String(body?.razorpay_signature||''),secret=process.env.RAZORPAY_KEY_SECRET;if(!orderId||!paymentId||!signature||!secret)return NextResponse.json({error:'Missing payment verification fields'},{status:400,headers:jsonSecurityHeaders()});if(!verifyRazorpayPaymentSignature(orderId,paymentId,signature,secret))return NextResponse.json({verified:false,error:'Invalid payment signature'},{status:400,headers:jsonSecurityHeaders()});const admin=createAdminClient(),{data:order,error:oe}=await admin.from('payment_orders').select('id,user_id,amount_paise,currency,credits,status').eq('razorpay_order_id',orderId).maybeSingle();if(oe||!order||order.user_id!==user.id)return NextResponse.json({error:'Payment order not found'},{status:404,headers:jsonSecurityHeaders()});if(order.status==='captured')return NextResponse.json({verified:true,credited:true,credits:order.credits},{headers:jsonSecurityHeaders()});const payment=await fetchRazorpayPayment(paymentId);if(payment.order_id!==orderId||payment.amount!==order.amount_paise||payment.currency!==order.currency||payment.status!=='captured')return NextResponse.json({error:'Payment could not be validated as captured'},{status:400,headers:jsonSecurityHeaders()});const{data,error}=await admin.rpc('grant_payment_credit',{p_order_id:orderId,p_payment_id:paymentId});if(error)return NextResponse.json({error:'Payment verified but credit could not be recorded. Retry verification.'},{status:500,headers:jsonSecurityHeaders()});return NextResponse.json({verified:true,credited:true,credits:order.credits,reference:data},{headers:jsonSecurityHeaders()});}catch(e){const status=e instanceof Error&&e.message==='REQUEST_TOO_LARGE'?413:400;return NextResponse.json({error:status===413?'Request too large':'Invalid payment verification request'},{status,headers:jsonSecurityHeaders()});}}
